    need_more:          "Preciso de pelo menos *2 cotações* para comparar{nm}. Você tem {n}.\n\nInsira a próxima: *País - Cidade - $Preço*",
    no_useful:          "Não consegui identificar a cidade ou o preço{nm} 😅\n\nVocê pode escrever assim:\n• *Medellín* (e te pergunto o preço)\n• *800* (e te pergunto a cidade)\n• *Colômbia - Medellín - $800* (formato completo)",
    comparison_header:  "📊 *Comparação de Destinos — Custo Total Real*\n*Procedimento: {procedure}*\n\n{table}\n\n{rec}\n\nVocê quer ver o *checklist pré-viagem* para viajar a {best}? Escreva *checklist*.",
    best_saving:        "✅ *{city}* oferece o melhor custo total, economizando *{saving}* vs a opção mais cara.",
    best_only:          "✅ *{city}* é sua melhor opção em custo total.",
    checklist_intro:    "✅ *Checklist Pré-Viagem — {best}*\n*Procedimento: {procedure}*\n\n{items}\n\n⚠️ *Importante:* Confirme os requisitos específicos com seu médico ao agendar. Esta lista é orientativa.\n\nHá algo mais em que eu possa te ajudar?",
    add_quote_prompt:   "Claro{nm}, insira a nova cotação:\n*País - Cidade - Preço*",
    connecting_sage_done:"Com certeza{nm}. Vou te conectar com *SAGE* 🩺 para preparar uma nova solicitação de cotação.",
    comparison_help:    "Como mais posso te ajudar{nm}?\n\n📋 Escreva *checklist* — Lista de preparação para {best}\n📊 Escreva *nova cotação* — Adicionar outra cotação\n🩺 Escreva *cotizar* — Preparar nova solicitação",
    post_checklist:     "Você tem alguma dúvida adicional sobre a viagem médica a {dest}{nm}? 🗺️\n\nEstou aqui para te ajudar no que precisar.",
    fallback:           "Olá{nm}, sou *ATLAS* 🗺️ seu conselheiro de turismo médico. Escreva *1* se tiver cotações ou *2* para explorar destinos.",
  }
};

const t = (key, vars) => {
  const L = STRINGS[LANG] || STRINGS.es;
  let str = L[key] || STRINGS.es[key] || key;
  if (vars) {
    for (const [k, v] of Object.entries(vars)) {
      str = str.split('{' + k + '}').join(v != null ? String(v) : '');
    }
  }
  return str;
};

let rt  = '';
let nag = 'ATLAS';
let nss = 'atlas_active';

// ── INTENCIONES GLOBALES ────────────────────────────────────
const wantsSchedule = /\bagendar\b|quiero (una )?cita|reservar cita|quiero agendar|me gustar[íi]a agendar|appointment|schedule an appointment|book a|marcar consulta|quero consulta|agendar consulta/i.test(txt);

if (wantsSchedule && state !== 'welcome' && state !== 'handoff_received') {
  const bestDest = atlas.best_destination;
  const destHint = bestDest ? ` en *${bestDest}*` : '';
  rt  = LANG === 'en'
    ? `Sure${nm}! Connecting you with *NOVA* 🌟 to schedule your appointment${destHint}.\n\nNOVA will help you find available doctors and book. On my way!`
    : LANG === 'pt'
    ? `Claro${nm}! Vou te conectar com *NOVA* 🌟 para agendar sua consulta${destHint}.\n\nNOVA vai te ajudar a encontrar médicos disponíveis. Já vou contigo!`
    : `Claro${nm}! Te conecto con *NOVA* 🌟 para gestionar tu cita${destHint}.\n\nNOVA te ayudará a encontrar médicos disponibles y agendar. ¡Ya voy contigo!`;
  nag = 'NOVA';
  nss = 'handoff_received';
  atlas.state = 'handoff_to_nova';
  return [{ json: {
    success: true, responseText: rt,
    newActiveAgent: nag, newSessionState: nss,
    newAtlasContext: atlas, inputContext: ctx,
    presetNovaState: 'gathering_appointment_city',
    userId: parseInt(inp.userId), sessionId: parseInt(inp.sessionId),
    userLanguage: inp.userLanguage || 'es', detectedLanguage: LANG,
    userName: inp.userName || null, remoteJid: inp.remoteJid, instance: inp.instance
  }}];
}

switch(state) {

  case 'welcome':
  case 'handoff_received': {
    const procHint = sage.procedure_name ? t('proc_hint', {procedure: sage.procedure_name}) : '';
    rt = t('welcome', {nm, proc_hint: procHint});
    atlas.state = 'has_quotes_check';
    atlas.procedure_type = procType;
    break;
  }

  case 'has_quotes_check': {
    const hasQ = /^[s1si]$|s[íi]|tengo|yes|cuento|i have|i do|sure|got|yep|tenho|sim/.test(txt);
    const noQ  = /\bno\b|^2$|todavía|aun|explorar|not yet|don't have|haven't|nope|explore|show me|não|ainda não/.test(txt);

    if (hasQ || allQuotes.length >= 1) {
      if (allQuotes.length >= 2) {
        atlas.state  = 'analyzing';
        atlas.quotes = allQuotes;
        rt = t('found_quotes', {nm, n: allQuotes.length});
      } else {
        atlas.state  = 'entering_quotes';
        atlas.quotes = allQuotes;
        rt = t('enter_quotes_prompt', {nm});
      }
    } else if (noQ) {
      atlas.state = 'exploring';
      if (destinations.length === 0) { rt = `...`; break; }
      const destLines = destinations
        .filter(d => d.city !== 'Miami')
        .map(d => {
          const rec       = d[recoveryField] || 3;
          const total_est = (d.avg_flight_cost_usd || 0) + ((d.avg_hotel_cost_per_night_usd || 70) * rec);
          return `🌎 *${d.city}, ${d.country}*\n   ✈️ ~${usd(d.avg_flight_cost_usd)} | 🏨 ~${usd(d.avg_hotel_cost_per_night_usd)}/noche | ⏱️ ${rec} días\n   💰 ~${usd(total_est)} (sin procedimiento)`;
        }).join('\n\n');
      rt = t('destinations_intro', {nm, lines: destLines});
    } else {
      rt = t('ask_1_or_2', {nm});
    }
    break;
  }

  case 'exploring': {
    const wantsSage    = /sage|nueva solicitud|new request|get a quote|quote request|nova solicitação|nova cotação|pedir cotação/i.test(txt);
    const wantsCompare = /compar|ver comparac|analiz|compare|show comparison|analyze|ver comparação|análise/i.test(txt);
    const wantsEnter   = /cotizac|ingresar|tengo cotizac|enter quote|add quote|i have a quote|have quotes|cotização|inserir|tenho cotação/i.test(txt);

    const priceMatch   = txt.match(/\$?([\d][\d,\.]*[\d])\s*(?:usd|dólares?|dolares?)?/i);
    const price        = priceMatch ? parseFloat(priceMatch[1].replace(/,/g,'')) : null;
    const destMatch    = destinations.find(d => txt.includes(d.city.toLowerCase()) || txt.includes(d.country.toLowerCase()));
    const hasQuoteFormat = !!(price && destMatch);

    if (wantsSage) {
      rt = t('connecting_sage', {nm});
      nag = 'SAGE'; nss = 'handoff_received'; atlas.state = 'handoff_to_sage';
    } else if (hasQuoteFormat) {
      const quotes = atlas.quotes || [];
      quotes.push({ destination_city: destMatch.city, destination_country: destMatch.country, procedure_cost: price });
      atlas.quotes = quotes;
      atlas.state  = 'entering_quotes';
      rt = quotes.length === 1 ? t('quote_reg_1', {nm, city: destMatch.city, price: usd(price)}) : t('quote_reg_n', {nm, n: quotes.length, city: destMatch.city, price: usd(price)});
    } else if (wantsCompare) {
      const quotes = atlas.quotes || [];
      if (quotes.length >= 2) {
        atlas.state = 'comparison_done';
        const analysis = quotes.map(q => {
          const d = destinations.find(d => d.city.toLowerCase() === q.destination_city.toLowerCase() || d.country.toLowerCase() === q.destination_country.toLowerCase());
          const flightCost = parseFloat(d ? d.avg_flight_cost_usd : 400);
          const hotelNight = parseFloat(d ? d.avg_hotel_cost_per_night_usd : 80);
          const recDays    = parseInt(d ? d[recoveryField] : 3);
          const totalCost  = parseFloat(q.procedure_cost) + flightCost + (hotelNight * recDays);
          return { ...q, flightCost, hotelNight, recDays, hotelCost: hotelNight * recDays, totalCost };
        }).sort((a, b) => a.totalCost - b.totalCost);
        atlas.analysis = analysis; atlas.best_destination = analysis[0].destination_city;
        const medals = ['🥇','🥈','🥉','4️⃣','5️⃣'];
        const table  = analysis.map((a, i) => `${medals[i]||`${i+1}.`} *${a.destination_city}, ${a.destination_country}*\n   💊 ${usd(a.procedure_cost)} | ✈️ ${usd(a.flightCost)} | 🏨 ${usd(a.hotelCost)} (${a.recDays}n)\n   💰 *TOTAL: ${usd(a.totalCost)}*`).join('\n\n');
        const saving = analysis.length > 1 ? analysis[analysis.length-1].totalCost - analysis[0].totalCost : 0;
        const rec    = saving > 0 ? t('best_saving', {city: analysis[0].destination_city, saving: usd(saving)}) : t('best_only', {city: analysis[0].destination_city});
        rt = t('comparison_header', {procedure: sage.procedure_name || procType, table, rec, best: analysis[0].destination_city});
      } else {
        rt = t('need_more', {nm, n: quotes.length});
      }
    } else if (wantsEnter) {
      atlas.state = 'entering_quotes';
      rt = t('enter_quotes_prompt', {nm});
    } else if (destMatch && !price) {
      atlas.pending_dest = { city: destMatch.city, country: destMatch.country };
      atlas.state = 'entering_quotes';
      rt = t('ask_price', {nm, city: destMatch.city});
    } else {
      rt = t('exploring_help', {nm});
    }
    break;
  }

  case 'entering_quotes': {
    const quotes = [...(atlas.quotes || [])];
    const wantsCompare = /compar|analiz|listo|ver|ok|calcula|suficiente|compare|calculate|ready|done|go|analyze|calcular|pronto/i.test(txt);
    const priceMatch   = txt.match(/\$?([\d][\d,\.]*[\d])\s*(?:usd|dólares?|dolares?)?/i);
    const price        = priceMatch ? parseFloat(priceMatch[1].replace(/,/g,'')) : null;
    const destMatch    = destinations.find(d => txt.includes(d.city.toLowerCase()) || txt.includes(d.country.toLowerCase()));
    const pendingDest  = atlas.pending_dest  || null;
    const pendingPrice = atlas.pending_price || null;
    const effectiveDest  = destMatch || pendingDest;
    const effectivePrice = price     || pendingPrice;

    if (effectiveDest && effectivePrice) {
      const newQuote = { destination_city: effectiveDest.city || effectiveDest, destination_country: effectiveDest.country || '', procedure_cost: effectivePrice };
      quotes.push(newQuote);
      atlas.quotes = quotes; atlas.pending_dest = null; atlas.pending_price = null;
      if (quotes.length < 2) { rt = t('quote_reg_1', {nm, city: newQuote.destination_city, price: usd(effectivePrice)}); }
      else { atlas.state = 'analyzing'; rt = t('quote_reg_n', {nm, n: quotes.length, city: newQuote.destination_city, price: usd(effectivePrice)}); }
    } else if (destMatch && !price && !wantsCompare) {
      atlas.pending_dest = { city: destMatch.city, country: destMatch.country }; atlas.pending_price = null;
      rt = t('ask_price', {nm, city: destMatch.city});
    } else if (price && !destMatch && !pendingDest && !wantsCompare) {
      atlas.pending_price = price; atlas.pending_dest = null;
      rt = t('ask_dest', {nm, price: usd(price)});
    } else if (wantsCompare && quotes.length < 2) {
      rt = t('need_more', {nm, n: quotes.length});
    } else if (!price && !destMatch && !wantsCompare) {
      rt = t('no_useful', {nm});
    }

    if ((wantsCompare || atlas.state === 'analyzing') && quotes.length >= 2) {
      atlas.state = 'comparison_done';
      const analysis = quotes.map(q => {
        const d = destinations.find(d => d.city.toLowerCase() === (q.destination_city||'').toLowerCase() || d.country.toLowerCase() === (q.destination_country||'').toLowerCase());
        const flightCost = parseFloat(d ? d.avg_flight_cost_usd : 400);
        const hotelNight = parseFloat(d ? d.avg_hotel_cost_per_night_usd : 80);
        const recDays    = parseInt(d ? d[recoveryField] : 3);
        const hotelCost  = hotelNight * recDays;
        const totalCost  = parseFloat(q.procedure_cost) + flightCost + hotelCost;
        return { ...q, flightCost, hotelNight, recDays, hotelCost, totalCost };
      }).sort((a, b) => a.totalCost - b.totalCost);
      atlas.analysis = analysis; atlas.best_destination = analysis[0].destination_city;
      const medals = ['🥇','🥈','🥉','4️⃣','5️⃣'];
      const table  = analysis.map((a, i) => `${medals[i]||`${i+1}.`} *${a.destination_city}, ${a.destination_country}*\n   💊 ${usd(a.procedure_cost)} | ✈️ ${usd(a.flightCost)} | 🏨 ${usd(a.hotelCost)} (${a.recDays}n)\n   💰 *TOTAL: ${usd(a.totalCost)}*`).join('\n\n');
      const saving = analysis.length > 1 ? analysis[analysis.length-1].totalCost - analysis[0].totalCost : 0;
      const rec    = saving > 0 ? t('best_saving', {city: analysis[0].destination_city, saving: usd(saving)}) : t('best_only', {city: analysis[0].destination_city});
      rt = t('comparison_header', {procedure: sage.procedure_name || procType, table, rec, best: analysis[0].destination_city});
    }
    break;
  }

  case 'analyzing': {
    const quotes = allQuotes.length > 0 ? allQuotes : (atlas.quotes || []);
    if (quotes.length < 2) { rt = t('need_more', {nm, n: quotes.length}); atlas.state = 'entering_quotes'; break; }
    atlas.state = 'comparison_done';
    const analysis = quotes.map(q => {
      const d = destinations.find(d => d.city.toLowerCase() === (q.destination_city||'').toLowerCase() || d.country.toLowerCase() === (q.destination_country||'').toLowerCase());
      const flightCost = parseFloat(d ? d.avg_flight_cost_usd : 400);
      const hotelNight = parseFloat(d ? d.avg_hotel_cost_per_night_usd : 80);
      const recDays    = parseInt(d ? d[recoveryField] : 3);
      const hotelCost  = hotelNight * recDays;
      const totalCost  = parseFloat(q.procedure_cost) + flightCost + hotelCost;
      return { ...q, flightCost, hotelNight, recDays, hotelCost, totalCost };
    }).sort((a, b) => a.totalCost - b.totalCost);
    atlas.analysis = analysis; atlas.best_destination = analysis[0].destination_city;
    const medals = ['🥇','🥈','🥉','4️⃣','5️⃣'];
    const table  = analysis.map((a, i) => `${medals[i]||`${i+1}.`} *${a.destination_city}, ${a.destination_country}*\n   💊 ${usd(a.procedure_cost)} | ✈️ ${usd(a.flightCost)} | 🏨 ${usd(a.hotelCost)} (${a.recDays}n)\n   💰 *TOTAL: ${usd(a.totalCost)}*`).join('\n\n');
    const saving = analysis.length > 1 ? analysis[analysis.length-1].totalCost - analysis[0].totalCost : 0;
    const rec    = saving > 0 ? t('best_saving', {city: analysis[0].destination_city, saving: usd(saving)}) : t('best_only', {city: analysis[0].destination_city});
    rt = t('comparison_header', {procedure: sage.procedure_name || procType, table, rec, best: analysis[0].destination_city});
    break;
  }

  case 'comparison_done': {
    const best           = atlas.best_destination || '—';
    const wantsChecklist = /checklist|lista|preparar|qué llev|llevar|documentos|preparacion|list|prepare|what to bring|documents|preparation|o que levar|preparação/i.test(txt);
    const wantsMore      = /más cotizac|otra cotizac|agregar|nueva|add quote|another quote|more quote|add another|mais cotação|outra cotação|adicionar/i.test(txt);
    const wantsSage      = /sage|nueva solicitud|otro procedimiento|new request|another procedure|new procedure|nova solicitação|outro procedimento/i.test(txt);

    if (wantsChecklist) {
      atlas.state = 'checklist_shown';
      const baseItems = [
        '📋 Pasaporte vigente (mín. 6 meses de validez) / Valid passport (min. 6 months)',
        '📄 Historial médico relevante / Relevant medical history',
        '💊 Lista de medicamentos actuales / Current medications list',
        '💳 Tarjeta de crédito internacional / International credit card',
        '📱 Seguro de viaje con cobertura médica / Travel insurance with medical coverage',
        '🏨 Reserva de hotel cerca de la clínica / Hotel reservation near clinic',
        '✈️ Vuelos con fecha flexible / Flexible return flights',
        '📞 Contacto de emergencia / Emergency contact'
      ];
      const dentalItems = [
        '🦷 Radiografías recientes / Recent X-rays (panoramic)',
        '📷 Fotografías de sonrisa / Smile photos (front + profile)',
        '⏰ Estadía mínima 3-7 días / Minimum stay 3-7 days',
        '🚫 Evitar fumar 48h antes / Avoid smoking 48h before'
      ];
      const plasticItems = [
        '📸 Fotos corporales frente/perfil/3/4 / Body photos front/profile/3-4',
        '🩺 Exámenes preoperatorios / Pre-op exams (blood, ECG)',
        '⏰ Estadía mínima 14-21 días / Minimum stay 14-21 days',
        '👕 Ropa cómoda / Comfortable loose clothing',
        '🚫 No fumar 2 semanas antes / No smoking 2 weeks before',
        '💊 Informar todos los medicamentos al cirujano / Disclose all medications'
      ];
      const extra    = procType === 'dental' ? dentalItems : plasticItems;
      const allItems = [...baseItems, ...extra].map((item, i) => `${i+1}. ${item}`).join('\n');
      rt = t('checklist_intro', {best, procedure: sage.procedure_name || procType, items: allItems});
    } else if (wantsMore) {
      atlas.state = 'entering_quotes';
      rt = t('add_quote_prompt', {nm});
    } else if (wantsSage) {
      rt = t('connecting_sage_done', {nm});
      nag = 'SAGE'; nss = 'handoff_received'; atlas.state = 'handoff_to_sage';
    } else {
      rt = t('comparison_help', {nm, best});
    }
    break;
  }

  case 'checklist_shown': {
    rt = t('post_checklist', {nm, dest: atlas.best_destination || '—'});
    break;
  }

  default: {
    rt = t('fallback', {nm});
    atlas.state = 'welcome';
  }
}

return [{ json: {
  success:           true,
  responseText:      rt,
  newActiveAgent:    nag,
  newSessionState:   nss,
  newAtlasContext:   atlas,
  inputContext:      ctx,
  userId:            parseInt(inp.userId),
  sessionId:         parseInt(inp.sessionId),
  userLanguage:      inp.userLanguage || 'es',
  detectedLanguage:  LANG,
  userName:          inp.userName || null,
  remoteJid:         inp.remoteJid,
  instance:          inp.instance
}}];

// ============================================================
// Construye la respuesta final de ATLAS.
// FIX v2.2.0: persiste language en newSessionContext (issue #3)
// ============================================================

const motor = $input.first().json;

if (!motor.success) {
  return [{ json: {
    success:        false,
    error:          motor.error || 'ATLAS_ENGINE_ERROR',
    responseText:   'Error interno en ATLAS. Por favor escribe de nuevo.',
