  }}];
}

const existingNova = motor.inputContext?.nova || {};

// Determinar idioma a persistir
const activeLang = motor.detectedLanguage || motor.userLanguage || 'es';

const newSessionContext = {
  ...(motor.inputContext || {}),
  atlas: motor.newAtlasContext,
  nova: motor.presetNovaState
    ? { ...existingNova, state: motor.presetNovaState }
    : existingNova,
  language: activeLang   // FIX #3: idioma persistente para toda la sesión
};

return [{ json: {
  success:            true,
  responseText:       motor.responseText,
  newActiveAgent:     motor.newActiveAgent  || 'ATLAS',
  newSessionState:    motor.newSessionState || 'atlas_active',
  newSessionContext,
  userId:             motor.userId,
  sessionId:          motor.sessionId,
  userLanguage:       motor.userLanguage    || 'es',
  userName:           motor.userName        || null,
  remoteJid:          motor.remoteJid,
  instance:           motor.instance
}}];

const e = $input.first().json;
return [{ json: {
  success:        false,
  error:          e.error   || 'ATLAS_ENGINE_ERROR',
  details:        e.details || [],
  responseText:   'Lo siento, tuve un problema técnico. Por favor escribe de nuevo en unos momentos.',
  newActiveAgent: 'ATLAS',
  _meta: { timestamp: new Date().toISOString(), source: 'atlas_error' }
}}];

// ============================================================
// PREPARAR NLG ATLAS v1.0 — Paso 4
// Inserta entre Motor y Construir Respuesta Final.
// Claude Sonnet hace narrativa de análisis más rica y personal.
// ============================================================
const raw   = $input.first().json;
const motor = raw._phi_clean || raw;

const atlasCtx = motor.newAtlasContext || {};
const state    = atlasCtx.state || '';
const LANG     = motor.detectedLanguage || motor.userLanguage || 'es';
const fn       = motor.userName ? motor.userName.split(' ')[0] : null;
const nm       = fn ? ` ${fn}` : '';
const sageCtx  = motor.inputContext?.sage || {};
const procedure = sageCtx.procedure_name || atlasCtx.procedure_type || '';

const LANG_NAMES = { es: 'español', en: 'English', pt: 'português' };
const langInstruction = LANG === 'es'
  ? 'Responde SIEMPRE en español.'
  : LANG === 'en'
  ? 'Always respond in English.'
  : 'Responda SEMPRE em português.';

// States where Claude adds real value
const CLAUDE_STATES = ['comparison_done', 'exploring', 'has_quotes_check', 'checklist_shown', 'analyzing'];
if (!CLAUDE_STATES.includes(state)) {
  return [{ json: { ...raw, _nlgSkip: true, _nlgReason: `skip_state:${state}` } }];
}

const usd = (n) => `$${parseFloat(n||0).toLocaleString('en-US',{minimumFractionDigits:0})} USD`;

let systemPrompt = '';
let userContent  = '';
let maxTokens    = 450;

// ─── comparison_done ────────────────────────────────────────
if (state === 'comparison_done' || state === 'analyzing') {
  const analysis = atlasCtx.analysis || [];
  const best     = analysis[0];

  const analysisStr = analysis.map((a, i) => {
    const medals = ['🥇','🥈','🥉'];
    return `${medals[i]||`${i+1}.`} ${a.destination_city}, ${a.destination_country}: procedimiento ${usd(a.procedure_cost)} + vuelo ${usd(a.flightCost)} + hotel ${usd(a.hotelCost)} (${a.recDays} noches) = TOTAL ${usd(a.totalCost)}`;
  }).join('\n');

  const saving = analysis.length > 1
    ? analysis[analysis.length-1].totalCost - analysis[0].totalCost
    : 0;

  systemPrompt = `Eres ATLAS, consejero de turismo médico de Pangi. Tu especialidad: ayudar a pacientes a tomar la mejor decisión sobre dónde realizarse un procedimiento médico.
${langInstruction}

PROCEDIMIENTO DEL PACIENTE: ${procedure || 'procedimiento médico'}
USUARIO: ${fn || 'paciente'}

ANÁLISIS DE DESTINOS:
${analysisStr}

${saving > 0 ? `El destino más económico ahorra ${usd(saving)} vs el más caro.` : ''}

TAREA: Escribe un análisis narrativo que:
1. Presente el destino ganador con entusiasmo fundamentado (no solo precio)
2. Explique brevemente POR QUÉ ese destino es la mejor opción para este procedimiento específico
3. Mencione el ahorro real en términos concretos
4. Invite a ver el checklist de preparación
5. Sea empático con la decisión del paciente (es una cirugía, no una compra de producto)

REGLAS:
- ${langInstruction}
- Máximo 8 líneas
- Formato WhatsApp (*negritas* para ciudad ganadora y cifras clave)
- Termina mencionando que puede escribir *checklist* para ver la lista de preparación
- NO uses emojis excesivos — máximo 3 emojis en todo el mensaje`;

  userContent = `Procedimiento: ${procedure}, mejor destino: ${best?.destination_city}`;
  maxTokens = 350;

// ─── exploring ───────────────────────────────────────────────
} else if (state === 'exploring') {
  const templateText = motor.responseText || '';

  systemPrompt = `Eres ATLAS, consejero de turismo médico de Pangi.
${langInstruction}

El paciente quiere explorar destinos de turismo médico para: ${procedure || 'un procedimiento médico'}

El sistema generó este listado base de destinos:
---
${templateText}
---

TAREA: Mantén todos los datos del listado pero mejora el texto que lo precede y lo sucede:
1. Abre con 1-2 líneas de contexto personalizado para este procedimiento
2. Incluye el listado exacto (no lo modifiques)
3. Cierra con una llamada a la acción natural para ingresar cotizaciones reales

${langInstruction} Máximo 3 líneas antes del listado, 2 líneas después.`;

  userContent = `Procedimiento: ${procedure}`;
  maxTokens = 500;

// ─── has_quotes_check ─────────────────────────────────────────
} else if (state === 'has_quotes_check') {
  systemPrompt = `Eres ATLAS, consejero de turismo médico de Pangi.
${langInstruction}

El paciente llega a ATLAS (probablemente con cotizaciones para ${procedure || 'un procedimiento médico'}).

TAREA: Escribe un mensaje de bienvenida breve (2-3 líneas) que:
1. Lo salude por nombre si disponible: ${fn || '(sin nombre)'}
2. Le explique brevemente qué hace ATLAS (costo total real = procedimiento + vuelo + hotel + recuperación)
3. Le pregunte si ya tiene cotizaciones de médicos (con las 2 opciones numéricas)

Formato WhatsApp. ${langInstruction}`;

  userContent = `Procedimiento: ${procedure || 'desconocido'}, usuario: ${fn || 'paciente'}`;
  maxTokens = 200;

// ─── checklist_shown ─────────────────────────────────────────
} else if (state === 'checklist_shown') {
  // FIX #4: cuando llega de SAGE sin cotizaciones, personalizar el mensaje
  // para que reconozca el contexto y no parezca que ignoró el pedido del usuario.
  const hasExistingQuotes = (atlasCtx.quotes || []).length > 0;
  const hasSageProcedure  = !!(sageCtx.procedure_name);

  if (!hasExistingQuotes && hasSageProcedure) {
    // Usuario llegó desde SAGE con procedimiento específico pero sin cotizaciones.
    // El motor ya generó el mensaje de bienvenida con "¿tienes cotizaciones? 1 o 2".
    // Claude lo personaliza para que tenga contexto del procedimiento de SAGE.
    const templateText = motor.responseText || '';
    systemPrompt = `Eres ATLAS, consejero de turismo médico de Pangi.
${langInstruction}

El paciente llegó porque quiere comparar destinos para: *${procedure || sageCtx.procedure_name}*
Su solicitud ya fue preparada por SAGE. Aún no tiene cotizaciones de médicos.

El sistema generó este mensaje base:
---
${templateText}
---

TAREA: Personaliza este mensaje para que:
1. Reconozca brevemente que vienen con su solicitud de *${sageCtx.procedure_name}* lista
2. Explique en 1 línea que para el análisis completo necesitan cotizaciones reales de médicos
3. Ofrezca las 2 opciones de forma clara: ver comparación real (cuando tengan cotizaciones) o explorar panorama de destinos ahora
4. Sea empático y motivador — ya dieron un gran paso al preparar la solicitud

${langInstruction}
Máximo 6 líneas. Formato WhatsApp (*negritas*).
Termina con: "¿Ya tienes cotizaciones de médicos? Escribe *1* para sí o *2* para explorar destinos." (en el idioma del usuario)
Responde SOLO con el texto del mensaje, sin JSON.`;

    userContent = `Procedure: ${sageCtx.procedure_name}, existing_quotes: 0`;
    maxTokens   = 250;
  } else {
    // Tiene cotizaciones o no viene de SAGE — saltar NLG
    return [{ json: { ...raw, _nlgSkip: true, _nlgReason: 'has_quotes_check_skip' }}];
  }

} else if (state === 'checklist_shown') {
  const bestDest     = atlasCtx.best_destination || '';
  const baseChecklist = motor.responseText || '';

  systemPrompt = `Eres ATLAS, consejero de turismo médico de Pangi.
${langInstruction}

El paciente va a viajar a ${bestDest} para realizarse: ${procedure || 'un procedimiento médico'}

El sistema generó este checklist base:
---
${baseChecklist}
---

TAREA: Mantén el checklist intacto pero añade 2-3 líneas de comentario personal ANTES del checklist, destacando los 2 items más críticos para este procedimiento específico.

${langInstruction} Conciso y tranquilizador.`;

  userContent = `Destino: ${bestDest}, procedimiento: ${procedure}`;
  maxTokens = 500;
}

return [{ json: {
  ...raw,
  _nlgSkip: false,
  _nlgState: state,
  claudeAtlasPayload: {
    model: 'claude-sonnet-4-20250514',
    max_tokens: maxTokens,
    system: systemPrompt,
    messages: [{ role: 'user', content: userContent }]
  }
}}];

// ============================================================
// PROCESAR NLG ATLAS v2.2.0 — Paso 4
// FIX v2.2.0: #4 — has_quotes_check state handled (transición suave)
// ============================================================
const httpResult = $json;
const prepData   = $('📦 Preparar — NLG ATLAS').first().json;

if (prepData._nlgSkip) {
  return [{ json: { ...prepData, _nlgSource: 'motor_skip' } }];
}

let finalOut = { ...prepData };
finalOut._nlgSource = 'motor_fallback';

try {
  const rawText = httpResult?.content?.[0]?.text?.trim();
  if (!rawText || rawText.length < 10) throw new Error('empty_response');

  const nlgState = prepData.newAtlasContext?.state || prepData._nlgState || '';

  // Para todos los estados que devuelven texto libre (no JSON)
  // usar directamente la respuesta de Claude
  if (['exploring','comparison_done','analyzing','checklist_shown',
       'has_quotes_check'].includes(nlgState)) {
    finalOut.responseText = rawText;
    finalOut._nlgSource   = 'claude_nlg';
  } else {
    finalOut.responseText = rawText;
    finalOut._nlgSource   = 'claude_nlg';
  }

} catch(e) {
  finalOut._nlgError = e.message;
}

return [{ json: finalOut }];

// ============================================================
// 🔐 Strip PHI v1.0
// Elimina identificadores personales antes de llamar a Claude.
// PHI eliminado: userName, userPhone, claudeContext.userName
// Datos completos preservados en el payload principal para
// nodos downstream (WhatsApp, DB, Construir Respuesta Final).
// ============================================================
const inp = $input.first().json;

const phiClean = {
  ...inp,
  userName:  null,
  userPhone: null,
  ...(inp.claudeContext
    ? { claudeContext: { ...inp.claudeContext, userName: null } }
    : {})
};

// _phi_clean excluye también remoteJid e instance
const { remoteJid, instance, userPhone, ...clinicalOnly } = phiClean;

return [{ json: {
  ...inp,              // datos completos para nodos posteriores
  phi_stripped: true,
  _phi_clean: {
    ...clinicalOnly,   // solo datos clínicos para Claude
    userName:  null,
    userPhone: null
  }
}}];

const prepData    = $('📦 Preparar — NLG ATLAS').first().json;
const claudeResp  = $input.first().json;

const sessionId    = prepData.sessionId || 'unknown';
const state        = prepData._nlgState || 'unknown';
const language     = prepData.detectedLanguage || prepData.userLanguage || 'es';
const model        = prepData.claudeAtlasPayload?.model || 'claude-sonnet-4-20250514';
const inputTokens  = claudeResp?.usage?.input_tokens  || 0;
const outputTokens = claudeResp?.usage?.output_tokens || 0;
const outputText   = claudeResp?.content?.[0]?.text   || '';

const PRICES = {
  'claude-sonnet-4-20250514':  { in: 3.00, out: 15.00 },
  'claude-haiku-4-5-20251001': { in: 0.80, out: 4.00  }
};
const p       = PRICES[model] || PRICES['claude-sonnet-4-20250514'];
const costUsd = ((inputTokens * p.in) + (outputTokens * p.out)) / 1_000_000;
const now     = new Date().toISOString();
const ts      = Date.now();

return [{ json: {
  _langfusePayload: {
    batch: [
      {
        id:        `trace-${sessionId}-${ts}`,
        type:      'trace-create',
        timestamp: now,
        body: {
          id:       `pangi-${sessionId}`,
          name:     `pangi-session-${sessionId}`,
          metadata: { session_id: sessionId, language, phi_stripped: prepData.phi_stripped || false }
        }
      },
      {
        id:        `atlas-${sessionId}-${ts}`,
        type:      'generation-create',
        timestamp: now,
        body: {
          id:        `gen-atlas-${sessionId}-${ts}`,
          traceId:   `pangi-${sessionId}`,
          name:      `atlas-${state}`,
          model,
          startTime: now,
          endTime:   now,
          input:  { prompt: (prepData.claudeAtlasPayload?.system || '').substring(0, 800) },
          output: { text: outputText.substring(0, 500) },
          usage:  { input: inputTokens, output: outputTokens, unit: 'TOKENS' },
          metadata: {
            agent:        'ATLAS',
            state,
            language,
            session_id:   sessionId,
            phi_stripped: prepData.phi_stripped || false,
            cost_usd:     parseFloat(costUsd.toFixed(6))
          }
        }
      }
    ]
  }
}}];
